      (ctx) => {
        const c = ctx.api('POST', '/v1/customers', { name: 'Plan Test Retrieve', email: 'retrieve.plan@example.test' }).body;
        ctx.assert(c && c.id, 'setup customer created');
        const ok = ctx.api('GET', '/v1/customers/' + c.id);
